// Claude's review tests for A34: draft code from the panel runs; from a web page it is refused.
// agy: do not edit this file.
import { describe, expect, it, vi } from 'vitest';
import { emptyState, type WemockState } from '../core/types';
import { isRunHandlerMessage, runHandler, type RunHandlerMessage, type RunnerIo } from './handlerRunner';

const EXT = 'extid';
const req = { method: 'GET', url: 'http://a.test/doc/7', headers: {} };
const draft = {
  code: 'return { id: params.id };',
  urlPattern: '/doc/:id',
  response: { status: 201, headers: { 'x-a': '1' }, body: '', bodyEncoding: 'text' as const, delayMs: 0 },
};
const msg: RunHandlerMessage = { type: 'run-handler', mockId: 'draft', request: req, draft };
const panel = { id: EXT, url: `chrome-extension://${EXT}/panel.html?tabId=1` };
const tab = { id: EXT, url: 'http://a.test/page', tab: { id: 1 } };

function io() {
  const runInOffscreen = vi.fn(async () => ({ ok: true as const, kind: 'json' as const, value: '{"id":"7"}', res: { status: 201, headers: {}, delayMs: 0 } }));
  const r: RunnerIo = { extensionId: EXT, loadState: async (): Promise<WemockState> => emptyState(), runInOffscreen };
  return { r, runInOffscreen };
}

describe('A34 draft runs', () => {
  it('the message shape: a draft must carry code, a pattern and a response', () => {
    expect(isRunHandlerMessage(msg)).toBe(true);
    expect(isRunHandlerMessage({ ...msg, draft: { ...draft, code: 5 } })).toBe(false);
    expect(isRunHandlerMessage({ ...msg, draft: { code: 'x' } })).toBe(false);
  });

  it('from the panel, the draft code runs with params from its own pattern, and nothing is read from storage', async () => {
    const { r, runInOffscreen } = io();
    const reply = await runHandler(msg, panel, r);
    expect(runInOffscreen).toHaveBeenCalledTimes(1);
    const sent = (runInOffscreen.mock.calls[0] as unknown as [{ code: string; input: { req: { params: Record<string, string> }; res: { status: number } } }])[0];
    expect(sent.code).toBe(draft.code);
    expect(sent.input.req.params).toEqual({ id: '7' });
    expect(sent.input.res.status).toBe(201);
    expect(reply.error).toBeUndefined();
  });

  it('from a web page, draft code is refused and never runs', async () => {
    const { r, runInOffscreen } = io();
    const reply = await runHandler(msg, tab, r);
    expect(runInOffscreen).not.toHaveBeenCalled();
    expect(reply.error).toMatch(/not accepted/i);
    expect(reply.response.status).toBe(500);
  });

  it('from another extension, refused too', async () => {
    const { r, runInOffscreen } = io();
    await runHandler(msg, { ...panel, id: 'other' }, r);
    expect(runInOffscreen).not.toHaveBeenCalled();
  });
});
